#include <iostream>

// Ham tra ve so lon hon giua hai so nguyen
// Chu ky ham: max(int, int)
int max(int num1, int num2) {
    if (num1 > num2) {
        return num1;
    } else {
        return num2;
    }
}

// Ham void: khong tra ve gia tri
void printBanner() {
    std::cout << "=== Maximum Finder ===\n";
}

int main() {
    printBanner();
    int a = 14;
    int b = 29;
    std::cout << "Max of " << a << " and " << b << " is " << max(a, b) << "\n";
    return 0;
}

#include <iostream>

// Listing 6.1: TestMax.cpp
// Tra ve gia tri lon hon giua hai so nguyen
[[nodiscard]] int max(int num1, int num2) {
    int result;
    if (num1 > num2) {
        result = num1;
    } else {
        result = num2;
    }
    return result;
}

int main() {
    int i = 5;
    int j = 2;

    // 1. Gan gia tri tra ve cho bien k
    int k = max(i, j);
    std::cout << "The maximum between " << i << " and " << j << " is " << k << "\n";

    // 2. Goi truc tiep trong bieu thuc xuat stream
    std::cout << "The maximum between 10 and 25 is " << max(10, 25) << "\n";

    return 0;
}
